<script setup lang="ts">
import { Tab, Tabs } from 'vant'
import { ref, watch } from 'vue'
import SekaiItem from './items/SekaiItem.vue'
import type { SimpleUniverseResponse } from '@/types/universe'
import { userService } from '@/services/user'
import { useUserStore } from '@/store/user'

interface Props {
  userId?: string
}
const props = defineProps<Props>()
const active = ref('Chatted')
const userStore = useUserStore()
const chattedSekaiList = ref<SimpleUniverseResponse[]>([])
const createdSekaiList = ref<SimpleUniverseResponse[]>([])
const favoriteSekaiList = ref<SimpleUniverseResponse[]>([])

watch(
  () => userStore.user,
  async (val) => {
    if (val) {
      await fetchSekaiList(active.value)
    }
  },
  { deep: true },
)

watch(
  () => active.value,
  async (val) => {
    await fetchSekaiList(val)
  },
)

async function fetchSekaiList(val: string) {
  if (!userStore.isLoggedIn) {
    return
  }

  if (val === 'Chatted') {
    chattedSekaiList.value = (await userService.getChattedSekai(props.userId)).data
  }
  else if (val === 'Created') {
    createdSekaiList.value = (await userService.getCreatedUniverses(props.userId)).data
    console.debug('createdSekaiList', createdSekaiList.value)
  }
  else if (val === 'Favorite') {
    favoriteSekaiList.value = (await userService.getFavoriteUniverses(props.userId)).data
  }
}
</script>

<template>
  <tabs
    v-model:active="active"
    class="tabs"
    @change="console.log('change', $event)"
    @click-tab="console.log('click-tab', $event)"
  >
    <tab key="chatted" title="Chatted" name="Chatted">
      <div class="grid-container">
        <sekai-item
          v-for="sekai in chattedSekaiList"
          :key="sekai.universeId"
          :sekai="sekai"
        />
      </div>
    </tab>
    <tab key="created" title="Created" name="Created">
      <div class="grid-container">
        <sekai-item
          v-for="sekai in createdSekaiList"
          :key="sekai.universeId"
          :sekai="sekai"
        />
      </div>
    </tab>
    <tab key="favorite" title="Favorite" name="Favorite">
      <div class="grid-container">
        <sekai-item
          v-for="sekai in favoriteSekaiList"
          :key="sekai.universeId"
          :sekai="sekai"
        />
      </div>
    </tab>
  </tabs>
</template>

