<script setup lang="ts">
import { useIonRouter } from '@ionic/vue'
import PencilIcon from './svg/PencilIcon.vue'
import MyAvatar from '@/components/MyAvatar.vue'
import type { User } from '@/types'
import { useAuthStore } from '@/store/auth'
import { useUserStore } from '@/store/user'
import { useGlobalStateStore } from '@/store/globalState'

interface Props {
  user: User
  me: boolean
}

interface Emits {
  (e: 'loginTriggered'): void
}

const props = defineProps<Props>()
defineEmits<Emits>()

const router = useIonRouter()
const authStore = useAuthStore()
const userStore = useUserStore()
const globalStore = useGlobalStateStore()

function handleGoToCreatedSekai() {
  if (!userStore.isLoggedIn) {
    authStore.openModal()
    return
  }

  router.push('/universes-list/created')
}

function handleGoFollowingList() {
  console.debug(userStore.isLoggedIn)
  if (!userStore.isLoggedIn) {
    authStore.openModal()
    return
  }
  router.push(`/follow?isFollower=false&userId=${props.user.userId}`)
}

function handleGoToFollowerList() {
  if (!userStore.isLoggedIn) {
    authStore.openModal()
    return
  }
  router.push(`/follow?isFollower=true&userId=${props.user.userId}`)
}
</script>

<template>
  <div class="flex flex-col gap-4">
    <div class="flex flex-grow items-center px-4">
      <my-avatar
        :user-name="user.userName"
        :src="user.userAvatarUrl"
        @click="() => $emit('loginTriggered')"
      />
      <div class="flex gap-6 px-4">
        <div
          class="flex flex-col items-center gap-1"
          @click="handleGoToCreatedSekai"
        >
          <p class="text-on-bg-1 text-5 fw-600">
            {{ user.createUniverseCount || 0 }}
          </p>
          <p class="text-on-bg-3 text-3.5 fw-600 leading-4.5">
            {{ $t("leftMenu.created") }}
          </p>
        </div>
        <div
          class="flex flex-col items-center gap-1"
          @click="handleGoFollowingList"
        >
          <p class="text-on-bg-1 text-5 fw-600">
            {{ user.followingCount || 0 }}
          </p>
          <p class="text-on-bg-3 text-3.5 fw-600 leading-4.5">
            Following
          </p>
        </div>
        <div
          class="flex flex-col items-center gap-1"
          @click="handleGoToFollowerList"
        >
          <p class="text-on-bg-1 text-5 fw-600">
            {{ user.followerCount || 0 }}
          </p>
          <p class="text-on-bg-3 text-3.5 fw-600 leading-4.5">
            Follower
          </p>
        </div>
      </div>
    </div>
    <div class="flex flex-col gap-1 px-4">
      <div class="flex gap-2">
        <p class="text-4 fw-700 text-white">
          {{ user.userName }}
        </p>
        <pencil-icon
          v-if="me"
          class="w-6 h-6"
          @click="
            () => {
              globalStore.setOpenNameChange(true);
            }
          "
        />
      </div>
      <p v-if="me" class="text-[#818181] text-3.5 fw-500 leading-normal">
        {{ `UID: ${user.userId}` }}
      </p>
    </div>
  </div>
</template>
